 var name strings.Builder
 for _,label:=range strings.Split(args[1],"."){if len(label)==0||len(label)>63{return fmt.Errorf("invalid label")}; for i:=0;i<len(label);i++{c:=label[i]; if c>='"'a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||c=='-'{name.WriteByte(c)}else{fmt.Fprintf(&name,\"\\\\%03d\",c)}}; name.WriteByte('.')}
